import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit } from "@/lib/event-bus";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

async function search(
  tenant: Tenant,
  q: string,
  kinds: Array<"issue" | "comment" | "project"> = ["issue", "comment", "project"],
  projectId?: Tenant["project"]["id"],
) {
  return searchService.search(tenant.actors.member, {
    orgId: tenant.org.id,
    q,
    kinds,
    ...(projectId ? { projectId } : {}),
    limit: 25,
    cursor: null,
  });
}

describe("search bugs", () => {
  it("starter colon title is literal and not refused", async () => {
    const starter = await createTenant("startercolon", "starter");
    await issueService.createIssue(
      starter.actors.member,
      issueInput(starter.org.id, starter.project.id, { title: "Release 2: hotfix" }),
    );
    const hits = await search(starter, "Release 2: hotfix", ["issue", "comment", "project"]);
    expect(hits.total).toBe(1);
    expect(hits.items[0]?.kind).toBe("issue");
  });

  it("enterprise kind and project tokens narrow", async () => {
    const ent = await createTenant("entsearch", "enterprise");
    const issue = await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "Deploy checklist" }),
    );
    await commentService.createComment(ent.actors.member, {
      orgId: ent.org.id,
      issueId: issue.id,
      body: "flaky deploy",
      parentId: null,
      mentionedUserIds: [],
    });

    const comments = await search(ent, "kind:comment flaky");
    expect(comments.total).toBe(1);
    expect(comments.items[0]?.kind).toBe("comment");

    const plural = await search(ent, "in:comments flaky");
    expect(plural.total).toBe(1);

    const scoped = await search(ent, `project:${ent.project.id} deploy`);
    expect(scoped.items.map((hit) => hit.kind).sort()).toEqual(["comment", "issue"]);

    const byFilter = await search(ent, "deploy", ["issue", "comment", "project"], ent.project.id);
    expect(byFilter.items.some((hit) => hit.kind === "comment")).toBe(true);
  });

  it("percent and underscore are literal", async () => {
    const ent = await createTenant("literals", "enterprise");
    await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "plain issue" }),
    );
    await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "progress 100%" }),
    );
    await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "snake case" }),
    );
    await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "snake_case" }),
    );

    const pct = await search(ent, "100%", ["issue"]);
    expect(pct.total).toBe(1);
    expect(pct.items[0]?.title).toContain("100%");

    const snake = await search(ent, "snake_case", ["issue"]);
    expect(snake.total).toBe(1);
    expect(snake.items[0]?.title).toContain("snake_case");
  });

  it("growth ignores requested comment kinds", async () => {
    const growth = await createTenant("growthsearch", "growth");
    const issue = await issueService.createIssue(
      growth.actors.member,
      issueInput(growth.org.id, growth.project.id, { title: "shared word" }),
    );
    await commentService.createComment(growth.actors.member, {
      orgId: growth.org.id,
      issueId: issue.id,
      body: "shared word in a comment",
      parentId: null,
      mentionedUserIds: [],
    });
    const hits = await search(growth, "shared word");
    expect(hits.total).toBe(1);
    expect(hits.items[0]?.kind).toBe("issue");
  });

  it("reindex covers comments and projects and skips archived issues", async () => {
    const ent = await createTenant("reindex", "enterprise");
    const issue = await issueService.createIssue(
